"use client";
import Link from "next/link";

import { useEffect, useState } from "react";

interface Camp {
    id: string;
    name: string;
    description: string;
    location: string;
    capacity: number;
}

const demoCamps: Camp[] = [
    { id: "1", name: "Найрамдал ОУХНЦ", description: "Монголын хамгийн анхны бөгөөд хамгийн том олон улсын хүүхдийн зуслан. Хүүхдийн хөгжилд чиглэсэн цогц хөтөлбөрүүд хэрэгжүүлдэг.", location: "Улаанбаатар хот", capacity: 500 },
    { id: "2", name: "Нарлаг", description: "Байгалийн үзэсгэлэнт газарт байрлах бөгөөд байгаль танин мэдэхүй, экологийн боловсрол олгох чиглэлээр голлон ажилладаг зуслан.", location: "Төв аймаг", capacity: 200 },
    { id: "3", name: "Цоглог", description: "Спорт, урлаг, англи хэлний төрөлжсөн хөтөлбөртэй бөгөөд хүүхэд залуучуудын өөрийгөө нээх таатай орчинг бүрдүүлдэг.", location: "Сэлэнгэ аймаг", capacity: 250 },
    { id: "4", name: "Галакси", description: "Шинжлэх ухаан, технологи, инновацийн чиглэлээр мэргэшсэн зуслангийн хөтөлбөр санал болгож байна.", location: "Дархан-Уул аймаг", capacity: 100 },
];

export default function CampsPage() {
    const [camps, setCamps] = useState<Camp[]>([]);
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        async function fetchCamps() {
            try {
                const response = await fetch("/api/camps");
                const data = await response.json();
                if (Array.isArray(data)) {
                    setCamps(data.length > 0 ? data : demoCamps);
                }
            } catch (error) {
                console.error("Failed to load camps", error);
            } finally {
                setLoading(false);
            }
        }

        fetchCamps();
    }, []);

    return (
        <div className="container mx-auto px-4 py-12 md:py-24">
            <div className="space-y-4 text-center mb-12">
                <h1 className="text-4xl font-bold tracking-tighter sm:text-5xl text-primary">Зуслангийн Каталог</h1>
                <p className="text-lg text-muted-foreground max-w-[700px] mx-auto">
                    Монголын Үндэсний Зуслангуудын Холбоонд бүртгэлтэй зуслангуудын мэдээллийн нэгдсэн сан.
                </p>
            </div>

            <div className="mb-8 flex flex-col sm:flex-row gap-4 justify-between items-center">
                <div className="w-full sm:max-w-xs">
                    <input
                        type="text"
                        placeholder="Зуслангийн нэрээр хайх..."
                        className="flex h-10 w-full rounded-md border border-input bg-background px-3 py-2 text-sm ring-offset-background file:border-0 file:bg-transparent file:text-sm file:font-medium placeholder:text-muted-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 disabled:cursor-not-allowed disabled:opacity-50"
                    />
                </div>
            </div>

            {loading ? (
                <div className="flex justify-center py-20">
                    <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-primary"></div>
                </div>
            ) : camps.length > 0 ? (
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                    {camps.map((camp) => (
                        <div key={camp.id} className="rounded-lg border bg-card text-card-foreground shadow-sm overflow-hidden flex flex-col">
                            <div className="aspect-video w-full bg-slate-100 flex items-center justify-center text-slate-400">
                                Зураг байхгүй
                            </div>
                            <div className="p-6 flex-1 flex flex-col">
                                <h3 className="text-2xl font-semibold leading-none tracking-tight mb-2">{camp.name}</h3>
                                <p className="text-sm text-muted-foreground mb-4 line-clamp-3">
                                    {camp.description || "Танилцуулга ороогүй байна."}
                                </p>
                                <div className="gap-2 mt-auto">
                                    <div className="text-sm flex items-center gap-2 mt-2">
                                        <span className="font-medium">Байршил:</span> {camp.location || "-"}
                                    </div>
                                    <div className="text-sm flex items-center gap-2 mt-1">
                                        <span className="font-medium">Хүчин чадал:</span> {camp.capacity ? `${camp.capacity} хүүхэд` : "-"}
                                    </div>
                                </div>
                                <div className="mt-6">
                                    <Link href={`/camps`} className="inline-flex items-center justify-center rounded-md text-sm font-medium ring-offset-background transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 disabled:pointer-events-none disabled:opacity-50 border border-input bg-background hover:bg-accent hover:text-accent-foreground h-10 px-4 py-2 w-full">
                                        Дэлгэрэнгүй үзэх
                                    </Link>
                                </div>
                            </div>
                        </div>
                    ))}
                </div>
            ) : (
                <div className="text-center py-20 border rounded-lg bg-slate-50">
                    <h3 className="text-lg font-medium text-slate-600">Одоогоор зуслангийн мэдээлэл оруулаагүй байна.</h3>
                    <p className="text-sm text-slate-500 mt-2">Админ хэсгээс зуслан нэмснээр энд харагдах болно.</p>
                </div>
            )}
        </div>
    );
}
